A click handler runs this code. When does the timer callback run?

```js
setTimeout(() => console.log('timer'), 0);
const end = Date.now() + 2000;
while (Date.now() < end) {} // busy-wait for 2 seconds
console.log('loop done');
```

What is logged?

```js
async function f() {
  console.log('1');
  await null;
  console.log('2');
}
f();
console.log('3');
```

You run this file with `node main.js` (a CommonJS script). What is logged?

```js
Promise.resolve().then(() => console.log('promise'));
process.nextTick(() => console.log('tick'));
console.log('sync');
```

What is logged in a browser?

```js
setTimeout(() => console.log('t1'), 0);
setTimeout(() => console.log('t2'), 0);
Promise.resolve().then(() => {
  console.log('p1');
  setTimeout(() => console.log('t3'), 0);
});
Promise.resolve().then(() => console.log('p2'));
```

Put the logged values in the order they appear in a browser.

```js
console.log('start');
setTimeout(() => {
  console.log('timeout 1');
  Promise.resolve().then(() => console.log('promise in timeout'));
}, 0);
setTimeout(() => console.log('timeout 2'), 0);
queueMicrotask(() => console.log('microtask'));
console.log('end');
```

What is logged?

```js
async function a() {
  console.log('a1');
  await b();
  console.log('a2');
}
async function b() {
  console.log('b');
}
a();
Promise.resolve().then(() => console.log('p'));
console.log('s');
```

What happens when this runs in a browser tab?

```js
function loop() {
  Promise.resolve().then(loop);
}
setTimeout(() => console.log('timer'), 0);
loop();
```

You run this CommonJS script with Node 20. Type the four labels in the order they are logged, separated by spaces.

```js
process.nextTick(() => console.log('n1'));
Promise.resolve().then(() => {
  console.log('p1');
  process.nextTick(() => console.log('n2'));
});
Promise.resolve().then(() => console.log('p2'));
```

A button has two click listeners:

```js
btn.addEventListener('click', () => {
  Promise.resolve().then(() => console.log('m1'));
  console.log('l1');
});
btn.addEventListener('click', () => {
  Promise.resolve().then(() => console.log('m2'));
  console.log('l2');
});
```

What is logged when a user clicks the button, and what is logged when a script calls `btn.click()`?

What is logged?

```js
const p = Promise.resolve();
(async () => { await p; console.log('A'); })();
p.then(() => console.log('B')).then(() => console.log('C'));
(async () => { await null; console.log('D'); })();
```

What does the user see after clicking this button?

```js
button.onclick = () => {
  status.textContent = 'Working…';
  heavyWork(); // 300 ms of synchronous work
  status.textContent = 'Done';
};
```

You run this as `node main.js` many times. What do you observe?

```js
setTimeout(() => console.log('timeout'), 0);
setImmediate(() => console.log('immediate'));
```

You run this CommonJS script with Node 20. Put the logged values in order.

```js
const fs = require('fs');
fs.readFile(__filename, () => {
  setTimeout(() => console.log('timeout'), 0);
  setImmediate(() => console.log('immediate'));
  process.nextTick(() => console.log('tick'));
});
Promise.resolve().then(() => console.log('promise'));
console.log('sync');
```

What is logged?

```js
const obs = new MutationObserver(() => console.log('mo'));
obs.observe(el, { attributes: true });
Promise.resolve().then(() => console.log('p1'));
el.setAttribute('data-x', '1');
Promise.resolve().then(() => console.log('p2'));
```

Put the logged values in order.

```js
async function x() {
  console.log('x1');
  await null;
  console.log('x2');
  await null;
  console.log('x3');
}
async function y() {
  console.log('y1');
  await null;
  console.log('y2');
}
x();
y();
```

What is logged?

```js
console.log(1);
setTimeout(() => console.log(2));
(async () => {
  console.log(3);
  await Promise.resolve();
  console.log(4);
  await new Promise((r) => setTimeout(r));
  console.log(5);
})();
Promise.resolve().then(() => console.log(6)).then(() => console.log(7));
console.log(8);
```

You run this file with Node.js 20 or later, using default flags. What happens?

```js
const p = Promise.reject(new Error('boom'));
setTimeout(() => {
  p.catch(() => console.log('caught'));
}, 0);
```

What is logged?

```js
const thenable = {
  then(resolve) {
    console.log('then called');
    resolve('v');
  },
};
(async () => { const v = await thenable; console.log('got', v); })();
Promise.resolve().then(() => console.log('p1')).then(() => console.log('p2'));
console.log('sync');
```

In Node 20, what does this log?

```js
setImmediate(() => console.log('i1'));
setImmediate(() => {
  console.log('i2');
  process.nextTick(() => console.log('n'));
  Promise.resolve().then(() => console.log('p'));
});
setImmediate(() => console.log('i3'));
```

Both callbacks below run in the same frame. What is logged?

```js
requestAnimationFrame(() => {
  console.log('raf1');
  Promise.resolve().then(() => console.log('micro'));
});
requestAnimationFrame(() => console.log('raf2'));
```

A Node service processes a 5-million-item array inside a request handler, believing the `await` lets other requests through:

```js
for (const item of items) {
  process(item); // fast, synchronous
  await Promise.resolve();
}
```

What actually happens to other requests and timers while the loop runs?
